#include "../src/vpl_encoder.hpp"
#include <fstream>
#include "../src/replay_mp4.hpp"
#include <iostream>
using Microsoft::WRL::ComPtr;
int main(int argc,char** argv){try{unsigned width=argc>1?std::stoul(argv[1]):1280,height=argc>2?std::stoul(argv[2]):720;bool direct=argc<4||std::string(argv[3])!="--copy";auto start=GetTickCount64();ComPtr<IDXGIFactory1> factory;arc::replayCheck(CreateDXGIFactory1(IID_PPV_ARGS(&factory)),"factory");ComPtr<IDXGIAdapter1> adapter;DXGI_ADAPTER_DESC1 desc{};for(UINT i=0;factory->EnumAdapters1(i,&adapter)!=DXGI_ERROR_NOT_FOUND;++i){adapter->GetDesc1(&desc);if(desc.VendorId==0x8086&&std::wstring(desc.Description).find(L"B390")!=std::wstring::npos)break;adapter.Reset();}if(!adapter)return 77;
 ComPtr<ID3D11Device> gpu;ComPtr<ID3D11DeviceContext> context;arc::replayCheck(D3D11CreateDevice(adapter.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT|D3D11_CREATE_DEVICE_VIDEO_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&gpu,nullptr,&context),"device");arc::VplEncoder encoder(gpu.Get(),context.Get(),desc.AdapterLuid,width,height,60,8,direct);
 D3D11_TEXTURE2D_DESC td{};td.Width=1280;td.Height=720;td.MipLevels=1;td.ArraySize=1;td.Format=DXGI_FORMAT_B8G8R8A8_UNORM;td.SampleDesc.Count=1;td.BindFlags=D3D11_BIND_RENDER_TARGET;ComPtr<ID3D11Texture2D> texture;ComPtr<ID3D11RenderTargetView> view;arc::replayCheck(gpu->CreateTexture2D(&td,nullptr,&texture),"texture");arc::replayCheck(gpu->CreateRenderTargetView(texture.Get(),nullptr,&view),"view");std::ofstream out("replay-hardware.obu",std::ios::binary);arc::ReplaySnapshot snapshot{width,height,60};unsigned count=0,keys=0;for(unsigned i=0;i<180;++i){float color[]={float(i%60)/60,.2f,.7f,1};context->ClearRenderTargetView(view.Get(),color);auto frame=encoder.encode(texture.Get(),uint64_t(i)*1500);if(frame){out.write(reinterpret_cast<const char*>(frame->bytes.data()),frame->bytes.size());if(snapshot.av1Config.empty())snapshot.av1Config=arc::av1Configuration(frame->bytes);arc::ReplayPacket packet;packet.pts=frame->pts;packet.key=frame->key;packet.size=frame->bytes.size();packet.memory=std::make_shared<const std::vector<uint8_t>>(frame->bytes);snapshot.packets.push_back(std::move(packet));++count;keys+=frame->key;}}out.close();std::filesystem::remove(std::filesystem::path("work")/"replay-hardware.mp4");arc::saveReplayMp4(std::filesystem::path("work")/"replay-hardware.mp4",snapshot);snapshot.endPts=10*90000;snapshot.trimStart=8*90000;std::filesystem::remove(std::filesystem::path("work")/"replay-static.mp4");arc::saveReplayMp4(std::filesystem::path("work")/"replay-static.mp4",snapshot);std::cout<<"Intel hardware AV1 packets="<<count<<" native="<<encoder.nativeWidth<<"x"<<encoder.nativeHeight<<" bindFlags="<<encoder.nativeBindFlags<<" direct="<<encoder.directFrames<<" copy="<<encoder.copyFrames<<" keys="<<keys<<" elapsedMs="<<GetTickCount64()-start<<"\n";return count>150&&keys>=2&&encoder.directFrames+encoder.copyFrames==180?0:1;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
